set-variable.value:
@{
                try {
                  var b = context.Response.Body.As<JObject>(preserveContent: true);
                  var ch = b == null ? null : b["choices"] as JArray;
                  if (ch == null) return "invalid";
                  var sb = new System.Text.StringBuilder();
                  foreach (var c in ch) {
                    var m = c["message"];
                    if (m == null) continue;
                    var content = m["content"];
                    string ct = "";
                    if (content != null && content.Type != JTokenType.Null) {
                      if (content.Type == JTokenType.String) ct = (string)content;
                      else {
                        var parts = content as JArray;
                        if (parts == null) return "invalid";
                        var text = new System.Text.StringBuilder();
                        foreach (var p in parts) {
                          var partText = p["text"];
                          if (partText != null && partText.Type == JTokenType.String) text.Append((string)partText).Append("\n");
                        }
                        ct = text.ToString();
                      }
                    }
                    if (ct.Length > 0) { if (sb.Length > 0) { sb.Append("
                "); } sb.Append(ct); }
                  }
                  string u = sb.ToString();
                  if (u.Trim().Length == 0) return "empty";
                  return u.Length > 10000 ? "oversized" : "ok";
                } catch (Exception) { return "invalid"; }
            }

@{
                if ((string)context.Variables["rp-cs-out-state"] != "ok") return "";
                var b = context.Response.Body.As<JObject>(preserveContent: true);
                var sb = new System.Text.StringBuilder();
                foreach (var c in (JArray)b["choices"]) {
                  var m = c["message"];
                  if (m == null) continue;
                  var content = m["content"];
                  string ct = "";
                  if (content != null && content.Type != JTokenType.Null) {
                    if (content.Type == JTokenType.String) ct = (string)content;
                    else {
                      var parts = content as JArray;
                      if (parts == null) throw new Exception("content");
                      var text = new System.Text.StringBuilder();
                      foreach (var p in parts) {
                        var partText = p["text"];
                        if (partText != null && partText.Type == JTokenType.String) text.Append((string)partText).Append("\n");
                      }
                      ct = text.ToString();
                    }
                  }
                  if (ct.Length > 0) { if (sb.Length > 0) { sb.Append("
                "); } sb.Append(ct); }
                }
                return new JObject(new JProperty("text", sb.ToString()), new JProperty("categories", new JArray("Hate", "SelfHarm", "Sexual", "Violence")), new JProperty("outputType", "FourSeverityLevels")).ToString(Newtonsoft.Json.Formatting.None);
            }

@{
                string st = (string)context.Variables["rp-cs-out-state"];
                if (st != "ok") return st;

                try {
                  var r = context.Variables.GetValueOrDefault<IResponse>("rp-out-resp");
                  if (r == null) return "null";
                  int s = r.StatusCode;
                  if (s == 200) {
                    var j = r.Body.As<JObject>();
                    var items = j == null ? null : j["categoriesAnalysis"] as JArray;
                    if (items == null) return "invalid";
                    var want = new System.Collections.Generic.List<string> { "Hate", "SelfHarm", "Sexual", "Violence" };
                    string cat = ""; int sev = 0;
                    foreach (var i in items) {
                      string c = (string)i["category"]; var sv = i["severity"];
                      if (c == null || sv == null || sv.Type != JTokenType.Integer || !want.Contains(c)) return "invalid";
                      want.Remove(c);
                      if ((int)sv > sev) { cat = c; sev = (int)sv; }
                    }
                    if (want.Count != 0) return "invalid";
                    return "ok:" + cat + ":" + sev.ToString();
                  }

                  if (s == 401 || s == 403) return "auth";
                  if (s == 408 || s == 429 || (s >= 500 && s <= 599)) return "dependency";
                  return "config";
                } catch (Exception) { return "invalid"; }
            }

@{
                string st = (string)context.Variables["rp-cs-out-state"];
                string a = (string)context.Variables["rp-out-result"];
                if (st == "empty") return "allow";
                bool over = a.StartsWith("ok:") && int.Parse(a.Split(':')[2]) >= {severity-threshold};
                if (over) return "block";
                if (!context.Variables.ContainsKey("rp-cs-token") || !(a.StartsWith("ok:") || a == "dependency")) return "error";
                if (a == "dependency") { return ((string)context.Variables["rp-safety-mode"]) == "regulated" ? "error" : "allowed_on_safety_error"; }
                return "allow";
            }

@{
                string o = (string)context.Variables["rp-out-decision"];
                string i = (string)context.Variables["rp-safety-decision"];
                return (o != "allow" || i == "allow") ? "output" : (string)context.Variables["rp-safety-phase"];
            }

@{
                string a = (string)context.Variables["rp-out-result"];
                if ((string)context.Variables["rp-safety-phase"] != "output" || !a.StartsWith("ok:")) return (string)context.Variables["rp-safety-category"];
                return a.Split(':')[1];
            }

@{
                string a = (string)context.Variables["rp-out-result"];
                if ((string)context.Variables["rp-safety-phase"] != "output" || !a.StartsWith("ok:")) return (string)context.Variables["rp-safety-severity"];
                return a.Split(':')[2];
            }

@{
                string o = (string)context.Variables["rp-out-decision"];
                string i = (string)context.Variables["rp-safety-decision"];
                if (o == "block" || o == "error") return o;
                if (o == "allowed_on_safety_error" || i == "allowed_on_safety_error") return "allowed_on_safety_error";
                return "allow";
            }
